function dessin(cote, niveau) {
  if (niveau<4) { 


    var cot=cote;
    var cotd=cot*cos(PI/4);
    texture(img);
    plane(cot);

    for (var i=0; i<4; i++) {

      rotateZ(i*HALF_PI);

      push();
      translate(cot/2, cot/2, 0);     
      rotateZ(PI/4);
       rotateX(tempo);
      rotateY(tempo);
      translate(cotd/2, 0, 0); 
      rotateZ(-PI/4);
      //triedre(50, 10);
      texture(img);
      plane(cot/2);
      dessin(cot/2, niveau+1);
      pop();
    }
  }
